test('REQ-5-3-1#6: REQ-5-3-1 -the requested workflow', async ({ page }) => {
  await openQ3Sales(page);
  await pasteBlock(page, 'A1', SHEET);

  await createPivot(page, 'A1', 'C4', 'A1:C4');
  await configurePivot(page, { Rows: 'Region', Values: 'Sales', 'Summarize by': 'SUM' });
  await expect(cell(page, 'B2')).toHaveText('1200');

  // delete the source header used by the pivot
  await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();
  await page.getByRole('columnheader', { name: 'B', exact: true }).click({ button: 'right' });
  await page.getByRole('menuitem', { name: 'Delete column', exact: true }).click();

  await page.getByRole('tab', { name: 'Pivot6', exact: true }).click();
  await page.getByRole('button', { name: 'Refresh pivot table', exact: true }).click();
  await expect(page.getByText('Pivot field is no longer available. Select a new field.', { exact: true })).toBeVisible();
  // the last successful result is preserved
  await expect(cell(page, 'A2')).toHaveText('East');
  await expect(cell(page, 'B2')).toHaveText('1200');

  // restore the source worksheet for the following scenarios
  await page.getByRole('tab', { name: 'Sheet1', exact: true }).click();
  await page.getByRole('columnheader', { name: 'B', exact: true }).click({ button: 'right' });
  await page.getByRole('menuitem', { name: 'Insert 1 column left', exact: true }).click();
  await setCell(page, 'B1', 'Sales');
  await setCell(page, 'B2', '1200');
  await setCell(page, 'B3', '800');
  await setCell(page, 'B4', '700');
  await expect(cell(page, 'B1')).toHaveText('Sales');
  await expect(cell(page, 'B2')).toHaveText('1200');
});

test('REQ-3-1-1: REQ-3-1-1 -the requested workflow,the requested workflow', async ({ page }) => {
  await openWorkbook(page);

  // Text entered through the formula bar, committed with Enter.
  await enterValue(page, 'D1', 'East');
  await expectCellText(page, 'D1', 'East');
  await expectFormulaBarValue(page, 'D1', 'East');

  // A number, committed by clicking another cell.
  await selectCell(page, 'D2');
  await formulaBar(page).fill('1200');
  await selectCell(page, 'A3');
  await expectCellText(page, 'D2', '1200');
  await expectFormulaBarValue(page, 'D2', '1200');

  // A formula cell: grid shows the result, formula bar shows the submitted formula.
  await enterValue(page, 'E1', '=D2*2');
  await expectCellText(page, 'E1', '2400');
  await expectFormulaBarValue(page, 'E1', '=D2*2');

  await reloadEditor(page);
  await expectCellText(page, 'D1', 'East');
  await expectCellText(page, 'D2', '1200');
  await expectCellText(page, 'E1', '2400');
  await expectFormulaBarValue(page, 'E1', '=D2*2');
});

test('REQ-4-1-1: REQ-4-1-1 -the requested workflow,the requested workflow', async ({ page }) => {
  await openSeededWorkbook(page);
  await expectCellText(page, 'A1', '2');
  await expectCellText(page, 'B1', '3');

  // Enter a basic expression directly in the grid through the inline editor.
  await cell(page, 'J7').dblclick();
  const editor = page.getByLabel('Edit J7', { exact: true });
  await editor.fill('=A1+B1');
  await editor.press('Enter');

  await expectCellText(page, 'J7', '5');
  await expectFormula(page, 'J7', '=A1+B1');

  await reloadEditor(page);
  await expectCellText(page, 'J7', '5');
  await expectFormula(page, 'J7', '=A1+B1');
});

test('REQ-4-1-1#4: REQ-4-1-1 -the requested workflow', async ({ page }) => {
  await openSeededWorkbook(page);

  // F12 is intentionally left empty: aggregates must ignore empty cells.
  await setCell(page, 'F10', '10');
  await setCell(page, 'F11', '20');
  await setCell(page, 'F13', '30');
  await setCell(page, 'G10', '=SUM(F10:F13)');
  await setCell(page, 'G11', '=AVERAGE(F10:F13)');
  await setCell(page, 'G12', '=MIN(F10:F13)');
  await setCell(page, 'G13', '=MAX(F10:F13)');

  await expectCellText(page, 'G10', '60');
  await expectCellText(page, 'G11', '20');
  await expectCellText(page, 'G12', '10');
  await expectCellText(page, 'G13', '30');
  await expectFormula(page, 'G10', '=SUM(F10:F13)');

  await reloadEditor(page);
  await expectCellText(page, 'G10', '60');
  await expectCellText(page, 'G11', '20');
  await expectCellText(page, 'G12', '10');
  await expectCellText(page, 'G13', '30');
  await expectFormula(page, 'G11', '=AVERAGE(F10:F13)');
});
